def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    doc = app.activeDocument
    prods = doc.products
    cam = adsk.cam.CAM.cast(prods.itemByProductType("CAMProductType"))
    for s in cam.setups:
        print("setup:", s.name, "ops:", s.operations.count, "machine:", s.machine.vendor if s.machine else None, s.machine.model if s.machine else None)
        print("  stock solids:", [b.name for b in s.stockSolids] if hasattr(s,'stockSolids') else "n/a")
        for p in s.parameters:
            try:
                print("   param:", p.name, "=", p.expression if hasattr(p,'expression') else p.value.value)
            except Exception as e:
                print("   param:", p.name, "err")
    des = adsk.fusion.Design.cast(prods.itemByProductType("DesignProductType"))
    root = des.rootComponent
    for b in root.bRepBodies:
        bb=b.boundingBox
        print("body:", b.name, [round(v*10,3) for v in bb.minPoint.asArray()], [round(v*10,3) for v in bb.maxPoint.asArray()])
    for o in root.occurrences:
        print("occ:", o.name)
    return None

