def run(_context):
    cam = mb.get_cam()
    s = [x for x in cam.setups if x.name=="Setup1"][0]
    tot=0
    for op in s.operations:
        try:
            t = cam.getMachiningTime(op, 1.0, 3000.0/6, 0)
            print(op.name, round(t.machiningTime,1), "s", "feed", round(t.feedDistance,1))
            tot += t.machiningTime
        except Exception as e:
            print(op.name, "err", e)
    print("TOTAL", round(tot/60,2), "min")
    return None

